int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> A(N + 1), px(N + 1, 0);
    for (int i = 1; i <= N; i++) {
        cin >> A[i];
        px[i] = px[i - 1] ^ A[i];
    }

    long long total = px[N];

    // If total XOR is non-zero:
    // Let common beauty be x and number of segments be k.
    // Then x xor x xor ... (k times) = total.
    // If k is even => total must be 0, impossible here.
    // So k is odd and x = total.
    // Therefore every segment must have XOR = total.
    // Count partitions where prefix XOR hits total, 0, total, 0, ... , total.
    if (total != 0) {
        long long cnt = 0;
        for (int i = 1; i < N; i++) {
            if (px[i] == total) cnt++;
        }
        // choose any subset of these cut positions, but valid cuts are exactly
        // after each completed segment. Number of ways equals 2^(cnt-1)? No.
        //
        // More directly:
        // Let positions where prefix XOR = total be p1 < p2 < ... < pm, and p_m = N.
        // A valid partition corresponds to choosing odd-numbered hits alternately with 0-hits.
        // Simpler standard fact: for total != 0, every valid cut must end a segment with XOR=total,
        // and segment starts after prefix XOR 0. This becomes equivalent to choosing any subset
        // of internal positions with prefix XOR = total that are reachable in sequence.
        //
        // Even simpler DP:
        long long dp0 = 1, dp1 = 0; // ways at current prefix with expected current prefix xor 0/total
        // Actually we process prefixes:
        // dp0: ways such that current segment start has prefix xor 0
        // dp1: ways such that current segment start has prefix xor total
        // Transition by ending segment when current prefix xor matches opposite.
        //
        // But since only two states matter, let's do it correctly.
        unordered_map<long long, long long> ways;
        ways.reserve(N * 2 + 10);
        ways[0] = 1;
        for (int i = 1; i <= N; i++) {
            long long cur = px[i];
            long long add = 0;
            auto it = ways.find(cur ^ total);
            if (it != ways.end()) add = it->second;
            if (i == N) {
                cout << add % MOD << '\n';
                return 0;
            }
            ways[cur] = (ways[cur] + add) % MOD;
        }
    }

    // total == 0
    // Then common beauty can be:
    // 1) x = 0, any number of segments, each segment XOR 0.
    // 2) x != 0, then number of segments must be even, and each segment XOR x.
    //
    // Count case 1:
    // Partition only at positions i<N with prefix xor 0.
    long long zeroCnt = 0;
    for (int i = 1; i < N; i++) if (px[i] == 0) zeroCnt++;
    long long ans = mod_pow(2, zeroCnt); // each zero-prefix position may or may not be cut

    // Count case 2:
    // For each x != 0, count partitions into an even number of segments each xor x.
    // Standard DP over occurrences between zeros.
    //
    // Let positions with prefix xor 0 split array into blocks.
    // For a fixed x, if cnt[i] is count of prefixes equal x before i-th zero block boundary,
    // recurrence collapses to Fibonacci-like accumulation.
    //
    // Efficient aggregate DP:
    // dp[v] = ways ending with an odd number of x-segments up to current zero block, for x=v
    // sum[v] counts occurrences of prefix xor v seen since start.
    vector<int> zeroPos;
    zeroPos.push_back(0);
    for (int i = 1; i <= N; i++) if (px[i] == 0) zeroPos.push_back(i);

    unordered_map<long long, long long> dp, cntMap;
    dp.reserve(N * 2 + 10);
    cntMap.reserve(N * 2 + 10);

    int lastZeroIdx = 0;
    for (int z = 1; z < (int)zeroPos.size(); z++) {
        int r = zeroPos[z];
        for (int i = lastZeroIdx + 1; i < r; i++) {
            cntMap[px[i]]++;
        }

        // At zero boundary, for every x seen in this block counts contribute:
        // new_dp[x] = dp[x] + cntMap[x]
        // More precisely standard recurrence:
        // if f_x = ways finishing at previous zero with odd count of x-segments,
        // and c_x = number of prefixes xor x before this zero since previous zero processing,
        // then f_x' = f_x + c_x * (f_x + 1)
        //
        // Derivation yields:
        // starting new even partition by choosing two x-segments around zero blocks, plus extending.
        for (auto &kv : cntMap) {
            long long x = kv.first;
            if (x == 0) continue;
            long long c = kv.second % MOD;
            long long old = dp[x];
            dp[x] = (old + c * (old + 1)) % MOD;
        }

        cntMap.clear();
        lastZeroIdx = r;
    }

    for (auto &kv : dp) {
        ans += kv.second;
        if (ans >= MOD) ans -= MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}

