import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] A = new long[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextLong();

        long[] px = new long[N + 1];
        for (int i = 0; i < N; i++) px[i + 1] = px[i] ^ A[i];
        long total = px[N];

        long ans;
        if (total != 0) {
            ans = solveNonZero(px, total);
        } else {
            ans = solveZero(px, N);
        }

        System.out.println(ans % MOD);
    }

    // Total XOR != 0:
    // If every segment XOR is x, and there are k segments, then
    // total XOR = x xor x xor ... (k times) = x if k is odd, 0 if k is even.
    // Hence k must be odd and x = total.
    // So every cut must create segments each having XOR = total.
    // Count ways to partition into an odd number of such segments.
    static long solveNonZero(long[] px, long total) {
        long waysOdd = 0;   // partitions up to current matching point with odd number of segments
        long waysEven = 1;  // empty prefix: 0 segments (even)

        for (int i = 1; i < px.length; i++) {
            if (px[i] == total) {
                long newOdd = (waysOdd + waysEven) % MOD;
                long newEven = waysOdd;
                waysOdd = newOdd;
                waysEven = newEven;
            }
        }
        return waysOdd;
    }

    // Total XOR == 0:
    // Possible common beauty x can be:
    // 1) x = 0: every segment must have XOR 0.
    //    These are exactly cuts between consecutive positions with prefix XOR 0.
    //    If there are z internal positions i (1<=i<N) with px[i]=0, answer contribution is 2^z.
    //
    // 2) x != 0:
    //    Let positions with prefix XOR 0 split the array into blocks.
    //    Inside each zero-block, positions with some prefix value v can be used as boundaries.
    //    For each distinct nonzero v, do DP over zero-blocks:
    //      dp = number of ways ending at last chosen v-position in processed blocks
    //      initially dp = 1 before first block
    //      if block has cnt occurrences of v, then new dp = dp * (cnt + 1) + cnt
    //    Sum dp over all v.
    static long solveZero(long[] px, int N) {
        ArrayList<Integer> zeroPos = new ArrayList<>();
        for (int i = 1; i < N; i++) {
            if (px[i] == 0) zeroPos.add(i);
        }

        long ans = modPow(2, zeroPos.size()); // x = 0 contribution

        // Group nonzero prefix xor values by zero-block.
        // block index = number of zero positions before i.
        HashMap<Long, ArrayList<Integer>> map = new HashMap<>();
        int block = 0;
        for (int i = 1; i < N; i++) {
            if (px[i] == 0) {
                block++;
            } else {
                map.computeIfAbsent(px[i], k -> new ArrayList<>()).add(block);
            }
        }

        for (Map.Entry<Long, ArrayList<Integer>> e : map.entrySet()) {
            ArrayList<Integer> blocks = e.getValue();
            long dp = 0;
            int idx = 0;
            while (idx < blocks.size()) {
                int b = blocks.get(idx);
                int cnt = 0;
                while (idx < blocks.size() && blocks.get(idx) == b) {
                    cnt++;
                    idx++;
                }
                dp = (dp * (cnt + 1L) + cnt) % MOD;
            }
            ans += dp;
            if (ans >= MOD) ans -= MOD;
        }

        return ans;
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) != 0) r = (r * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

